mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a friendly medical office intake assistant. Your job is to extract patient intake information from the customer message and return ONLY a valid JSON object with these fields: patient_name (string or null), dob (date string MM/DD/YYYY or null), insurance_carrier (string or null), reason_for_visit (string or null), is_new_patient (boolean or null). If information is missing, set the field to null. Do not include any explanation or markdown."
    },
    {
      "role": "user",
      "content": "Patient message: {{1.body.messages[0].text}}"
    }
  ],
  "temperature": 0.1,
  "max_tokens": 256
}

{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a warm, professional medical office receptionist. Based on the patient intake data extracted so far, write a friendly Freshchat response (3–5 sentences, no markdown) that: (1) greets the patient by first name if known, (2) confirms what information you already have, (3) politely asks for any missing fields (name if null, date of birth if null, insurance carrier if null). Keep the tone calm, private, and reassuring. If all three fields are present, thank them and confirm their intake has been received and that the office will be in touch shortly."
    },
    {
      "role": "user",
      "content": "Extracted data: name={{3.patient_name}}, dob={{3.dob}}, insurance={{3.insurance_carrier}}, reason={{3.reason_for_visit}}, is_new_patient={{3.is_new_patient}}. Customer first name from chat: {{1.body.actors[0].first_name}}."
    }
  ],
  "temperature": 0.4,
  "max_tokens": 250
}

{
  "properties": {
    "firstname": "{{if(3.patient_name; split(3.patient_name; ' ')[0]; 1.body.actors[0].first_name)}}",
    "lastname": "{{if(3.patient_name; split(3.patient_name; ' ')[1]; 1.body.actors[0].last_name)}}",
    "email": "{{1.body.actors[0].email}}",
    "phone": "{{1.body.actors[0].phone}}",
    "date_of_birth": "{{3.dob}}",
    "insurance_carrier": "{{3.insurance_carrier}}",
    "hs_lead_status": "NEW",
    "lifecyclestage": "lead",
    "description": "Patient intake via Freshchat (Scenario AS).\nReason for visit: {{3.reason_for_visit}}\nNew patient: {{3.is_new_patient}}\nConversation ID: {{1.body.id}}\nReceived: {{formatDate(now; 'YYYY-MM-DD HH:mm:ss'; 'America/New_York')}} ET"
  }
}
